<?php
namespace App\Jobs;
use App\Mail\NewReservationMail; use App\Mail\ReservationConfirmedMail; use App\Models\Reservation; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Mail;
class SendReservationNotifications implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public function __construct(public int $reservationId){} public function handle():void{$r=Reservation::with(['shop','service','staff'])->find($this->reservationId);if(!$r)return;try{Mail::to($r->email)->send(new ReservationConfirmedMail($r));}catch(\Throwable$e){Log::error('Customer reservation mail failed',['reservation_id'=>$r->id,'error'=>$e->getMessage()]);}try{if($r->shop->email)Mail::to($r->shop->email)->send(new NewReservationMail($r));}catch(\Throwable$e){Log::error('Admin reservation mail failed',['reservation_id'=>$r->id,'error'=>$e->getMessage()]);}} }
